std::map<int, char> M = {{1,'a'}, {5,'e'}, {10,'j'}};

// Single Element Lookup (O(log N))
auto it_find = M.find(5);

// Count occurrences (0 or 1 for map/set)
size_t cnt = M.count(10);

// Range Lower Bound (First element >= key)
auto lower = M.lower_bound(3); // points to {5, 'e'}

// Range Upper Bound (First element > key)
auto upper = M.upper_bound(5);  // points to {10, 'j'}

// Combined Range (Pair of iterators)
auto range = M.equal_range(5);
// Iterate: for (auto it = range.first; it != range.second; ++it)
